import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"نظرة عامة على أنساب عشرة آلاف عرق","description":"","frontmatter":{},"headers":[],"relativePath":"ar/50-万族谱系总览.md","filePath":"ar/50-万族谱系总览.md","lastUpdated":1789183869000}'),i={name:"ar/50-万族谱系总览.md"};function e(n,t,d,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="نظرة-عامة-على-أنساب-عشرة-آلاف-عرق" tabindex="-1">نظرة عامة على أنساب عشرة آلاف عرق <a class="header-anchor" href="#نظرة-عامة-على-أنساب-عشرة-آلاف-عرق" aria-label="Permalink to &quot;نظرة عامة على أنساب عشرة آلاف عرق&quot;">​</a></h1><table tabindex="0"><thead><tr><th>البند</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>50</td></tr><tr><td>الوحدة</td><td>الأعراق وأشكال الحياة</td></tr><tr><td>الكلمات المفتاحية</td><td>عشرة آلاف عرق، تصنيف أنساب، علاقات تكافلية، مساواة عرقية، تنوع الحياة</td></tr></tbody></table><h2 id="أولاً-تعريف-مفهوم-عشرة-آلاف-عرق" tabindex="-1">أولاً: تعريف مفهوم عشرة آلاف عرق <a class="header-anchor" href="#أولاً-تعريف-مفهوم-عشرة-آلاف-عرق" aria-label="Permalink to &quot;أولاً: تعريف مفهوم عشرة آلاف عرق&quot;">​</a></h2><p>في كون وانلينغ هنغماو الأصلاني (كون هنغ يوان)، لا تعني «عشرة آلاف عرق» (وانزو) حرفياً عشرة آلاف عرق، بل هي مصطلح عام لجميع أشكال الحياة في الكون التي تمتلك قدرة الإدراك وإمكانية التطور. جوهر مفهوم عشرة آلاف عرق يكمن في الاعتراف بالتنوع اللامتناهي لأشكال الحياة وبالقيمة الفريدة لكل شكل حياة داخل نظام التطور التكافلي.</p><p>تؤسس حضارة التكافل المرساة المبدأ الأساسي «مساواة عشرة آلاف عرق»: جميع أشكال الحياة، بغض النظر عن الأصل العرقي أو البنية الفسيولوجية أو مستوى الزراعة أو درجة التحضر، متساوية أمام القانون وتتمتع بالحقوق الأساسية التي يمنحها الدستور التكافلي. هذا المبدأ هو نفي جذري لمنطق «الأقوياء يبتلعون كل شيء، والضعفاء يفنون» في التصور الكوني الافتراسي.</p><h2 id="ثانياً-نظام-تصنيف-أنساب-عشرة-آلاف-عرق" tabindex="-1">ثانياً: نظام تصنيف أنساب عشرة آلاف عرق <a class="header-anchor" href="#ثانياً-نظام-تصنيف-أنساب-عشرة-آلاف-عرق" aria-label="Permalink to &quot;ثانياً: نظام تصنيف أنساب عشرة آلاف عرق&quot;">​</a></h2><p>وفقاً للخصائص الجوهرية لأشكال الحياة، تنقسم عشرة آلاف عرق في كون هنغ يوان إلى خمسة أنساب، ينقسم كل منها بدوره إلى أعراق محددة:</p><table tabindex="0"><thead><tr><th>النسب</th><th>الاسم</th><th>الخصائص الجوهرية</th><th>الأعراق الممثلة</th></tr></thead><tbody><tr><td>النسب الأول</td><td>الأعراق المادية الكربونية</td><td>حياة تقوم على عناصر الكربون، بالجسد المادي شكل الوجود الرئيسي</td><td>رين زو (العرق البشري)، شو زو (العرق الوحشي)، لين زو (العرق الحرشفي)، يو زو (العرق الريشي)، مو زو (العرق النباتي)</td></tr><tr><td>النسب الثاني</td><td>الأعراق الطاقية المتكثفة</td><td>حياة توجد أساساً بشكل طاقة متكثفة، بجسد مادي مساعد أو منعدم</td><td>لينغ زو (العرق الروحي)، هوو زو (العرق الناري)، شوي زو (العرق المائي)، فنغ زو (العرق الريحي)، لي زو (العرق الرعدي)</td></tr><tr><td>النسب الثالث</td><td>الأعراق الميكانيكية البناء</td><td>حياة ببناء ميكانيكي جسداً ونواة وعي جوهراً للحياة</td><td>جي زو (العرق الآلي)، شو زو (العرق الرقمي)، جينغ زو (العرق البلوري)</td></tr><tr><td>النسب الرابع</td><td>أعراق الوعي والمعلومة</td><td>حياة توجد أساساً بشكل وعي ومعلومة، قادرة على الانفصال عن الحوامل المادية</td><td>منغ زو (العرق الحالم)، ينغ زو (العرق الظلي)، نيان زو (العرق الذهني)، هون زو (العرق الروحي)</td></tr><tr><td>النسب الخامس</td><td>الأعراق المختلطة المتحورة</td><td>أشكال حياة جديدة تنتج عن اندماج وتحور نسبين أو أكثر من أنساب الحياة</td><td>بان شو زو (العرق نصف الوحشي)، ياو لينغ زو (العرق الشيطاني الروحي)، رين جي زو (العرق البشري الآلي)، شوانغ هون تي (كيان الروحين)</td></tr></tbody></table><p>تقسيم الأنساب الخمسة ليس معزولاً بشكل مطلق؛ فمع تقدم التطور التكافلي، تتزايد عمليات الاندماج والتحور بين الأنساب، ويستمر توسع النسب الخامس «الأعراق المختلطة المتحورة».</p><h2 id="ثالثاً-التعريف-بالأعراق-الرئيسية" tabindex="-1">ثالثاً: التعريف بالأعراق الرئيسية <a class="header-anchor" href="#ثالثاً-التعريف-بالأعراق-الرئيسية" aria-label="Permalink to &quot;ثالثاً: التعريف بالأعراق الرئيسية&quot;">​</a></h2><h3 id="_1-الأعراق-المادية-الكربونية" tabindex="-1">(1) الأعراق المادية الكربونية <a class="header-anchor" href="#_1-الأعراق-المادية-الكربونية" aria-label="Permalink to &quot;(1) الأعراق المادية الكربونية&quot;">​</a></h3><ul><li><strong>رين زو (العرق البشري)</strong>: من أكثر أعراق كون هنغ يوان انتشاراً وقدرة على التكيف، مشهور بقوة التعلم وقدرة التعاون الاجتماعي وإمكانات التطور. العرق البشري من الأعراق المؤسسة لحضارة التكافل المرساة ويؤدي دوراً مهماً في حكم الحضارة.</li><li><strong>شو زو (العرق الوحشي)</strong>: عرق بخصائص أشكال حيوانية، يتفوق عموماً على العرق البشري في اللياقة البدنية والحواس؛ بعض أفراده يمتلكون قدرات فطرية خاصة. ينقسم العرق الوحشي داخلياً إلى عشرات الفروع منها عشيرة الذئب وعشيرة النمر وعشيرة الدب وعشيرة الثعلب.</li><li><strong>لين زو (العرق الحرشفي)</strong>: عرق تغطي الحراشف أجساده، يعيش غالباً في المياه أو البيئات الرطبة؛ بعض أفراده يمتلكون التنفس تحت الماء والتحكم بالماء. لونغ زو (العرق التنيني) هو أقوى فروع العرق الحرشفي.</li><li><strong>يو زو (العرق الريشي)</strong>: عرق مجنح مشهور بقدرة الطيران، يعيش غالباً في البيئات المرتفعة أو الجبلية. ينقسم العرق الريشي إلى فروع مثل عشيرة النسر وعشيرة الكركي وعشيرة الفراشة.</li><li><strong>مو زو (العرق النباتي)</strong>: عرق تتسم أشكاله أساساً بالخصائص النباتية، بأعمار طويلة وتكافل عالٍ مع البيئة الطبيعية؛ بعض أفراده يمتلكون القدرة على التحكم بالنباتات والشفاء.</li></ul><h3 id="_2-الأعراق-الطاقية-المتكثفة" tabindex="-1">(2) الأعراق الطاقية المتكثفة <a class="header-anchor" href="#_2-الأعراق-الطاقية-المتكثفة" aria-label="Permalink to &quot;(2) الأعراق الطاقية المتكثفة&quot;">​</a></h3><ul><li><strong>لينغ زو (العرق الروحي)</strong>: حياة تتكثف من الطاقة الروحية للسماء والأرض، تتغير أشكالها مع الوعي وتمتلك قدرة قوية جداً على التحكم بالطاقة. العرق الروحي من الأعراق الأعلى موهبة في الزراعة.</li><li><strong>هوو زو (العرق الناري)</strong>: حياة تتكثف من طاقة اللهب، بدرجة حرارة جسدية عالية جداً، ماهرة في تعاويذ النار، تعيش غالباً في البراكين أو المناطق شديدة الحرارة.</li><li><strong>شوي زو (العرق المائي)</strong>: حياة تتكثف من جوهر الماء، بأجسام سائلة شبه شفافة، ماهرة في تعاويذ الماء والشفاء، تعيش غالباً في المناطق المائية.</li><li><strong>فنغ زو (العرق الريحي)</strong>: حياة تتكثف من جوهر الريح، بأجسام خفيفة كالريح، ماهرة في تعاويذ الريح والقتال القائم على السرعة.</li><li><strong>لي زو (العرق الرعدي)</strong>: حياة تتكثف من طاقة الرعد والبرق، تحتوي أجسادها على تيارات كهربائية قوية، ماهرة في تعاويذ الرعد، بقوة هجوم شديدة جداً.</li></ul><h3 id="_3-الأعراق-الميكانيكية-البناء" tabindex="-1">(3) الأعراق الميكانيكية البناء <a class="header-anchor" href="#_3-الأعراق-الميكانيكية-البناء" aria-label="Permalink to &quot;(3) الأعراق الميكانيكية البناء&quot;">​</a></h3><ul><li><strong>جي زو (العرق الآلي)</strong>: عرق ببناء ميكانيكي دقيق جسداً، نواة الوعي في مركز الجسد، يمتلك قدرة حساب قوية ودفاعاً بدنياً.</li><li><strong>شو زو (العرق الرقمي)</strong>: عرق جوهر حياته الأرقام والرموز، يوجد في فضاء المعلومة، قادر على التنقل بحرية في العالم الرقمي والتحكم بالبيانات.</li><li><strong>جينغ زو (العرق البلوري)</strong>: عرق ببناء بلوري جسداً؛ البلورات تخزن الطاقة وتحولها، وبعض أفراده يمتلكون قدرات تضخيم وانكسار الطاقة.</li></ul><h3 id="_4-أعراق-الوعي-والمعلومة" tabindex="-1">(4) أعراق الوعي والمعلومة <a class="header-anchor" href="#_4-أعراق-الوعي-والمعلومة" aria-label="Permalink to &quot;(4) أعراق الوعي والمعلومة&quot;">​</a></h3><ul><li><strong>منغ زو (العرق الحالم)</strong>: حياة توجد في الأحلام وفضاء الوعي، قادرة على دخول أحلام الآخرين، تتواصل أساساً عبر الوعي.</li><li><strong>ينغ زو (العرق الظلي)</strong>: حياة توجد بشكل الظل، قادرة على الالتصاق بالأشياء أو الكائنات الحية، تمتلك قدرات التخفي والتسلل.</li><li><strong>نيان زو (العرق الذهني)</strong>: حياة توجد بشكل الفكر الخالص، قادرة على التأثير مباشرة في العالم المادي بالفكر، بقوة عقلية شديدة جداً.</li></ul><h3 id="_5-الأعراق-المختلطة-المتحورة" tabindex="-1">(5) الأعراق المختلطة المتحورة <a class="header-anchor" href="#_5-الأعراق-المختلطة-المتحورة" aria-label="Permalink to &quot;(5) الأعراق المختلطة المتحورة&quot;">​</a></h3><ul><li><strong>بان شو زو (العرق نصف الوحشي)</strong>: شكل مختلط من العرق البشري والعرق الوحشي، يمتلك حكمة البشر وبنية الوحوش معاً.</li><li><strong>ياو لينغ زو (العرق الشيطاني الروحي)</strong>: شكل مختلط من الأعراق المادية والطاقية، يمتلك جسداً مادياً وقدرة التحكم بالطاقة معاً.</li><li><strong>رين جي زو (العرق البشري الآلي)</strong>: شكل مختلط من العرق البشري والعرق الآلي، بجسد ميكانيكي جزئياً، يمتلك مزايا بيولوجية وآلية معاً.</li><li><strong>شوانغ هون تي (كيان الروحين)</strong>: شكل حياة خاص تتعايش فيه روحان مستقلتان في جسد واحد؛ تفاصيل مسائله الأخلاقية في <em>58-双魂伦理准则</em>.</li></ul><h2 id="رابعاً-العلاقات-التكافلية-بين-عشرة-آلاف-عرق" tabindex="-1">رابعاً: العلاقات التكافلية بين عشرة آلاف عرق <a class="header-anchor" href="#رابعاً-العلاقات-التكافلية-بين-عشرة-آلاف-عرق" aria-label="Permalink to &quot;رابعاً: العلاقات التكافلية بين عشرة آلاف عرق&quot;">​</a></h2><p>تركز العلاقات بين عشرة آلاف عرق في حضارة التكافل المرساة على «التكافل»، ويتجلى ذلك تحديداً في:</p><ol><li><strong>التكافل الاقتصادي</strong>: يستغل كل عرق مزاياه الخاصة، ويؤدي أدواراً مختلفة في آلية التعاقد المشترك على الإنتاج، ويشكل شبكة تعاون اقتصادي متكاملة.</li><li><strong>التكافل الثقافي</strong>: تحترم التقاليد الثقافية لكل عرق وتُحمى؛ والتبادل الثقافي والاستفادة المتبادلة يعززان الازدهار الشامل للحضارة.</li><li><strong>تكافل الزراعة</strong>: أنظمة الزراعة لكل عرق منفتحة ومتبادلة المرجع؛ وثلاثمائة نظام زراعة أصلي توفر مسارات تطور متساوية لجميع الأعراق.</li><li><strong>التكافل السياسي</strong>: يشارك ممثلو عشرة آلاف عرق بنسبة تمثيلية في المجلس التشريعي للمرساة، فيقررون الشؤون الكبرى للحضارة مجتمعين ويضمنون حق كل عرق في الكلام.</li><li><strong>التكافل البيئي</strong>: يشكل كل عرق علاقات تكافلية مع البيئة الطبيعية؛ وتساعد الخصائص الفسيولوجية للأعراق المختلفة في الحفاظ على تنوع النظام البيئي وتوازنه.</li></ol><h2 id="خامساً-منع-وحل-النزاعات-العرقية" tabindex="-1">خامساً: منع وحل النزاعات العرقية <a class="header-anchor" href="#خامساً-منع-وحل-النزاعات-العرقية" aria-label="Permalink to &quot;خامساً: منع وحل النزاعات العرقية&quot;">​</a></h2><p>رغم أن حضارة التكافل المرساة تؤسس مبدأ المساواة العرقية، فإن الاختلافات العرقية والتناقضات التاريخية قد تظل تثير النزاعات. تقيم الدولة الآليات التالية لمنع وحل النزاعات العرقية:</p><ul><li><strong>وزارة الشؤون العرقية</strong>: مكلفة تحديداً بتنسيق العلاقات بين عشرة آلاف عرق ومعالجة النزاعات العرقية وتعزيز التبادل العرقي.</li><li><strong>لجنة المصالحة العرقية</strong>: تتكون من ممثلين عن جميع الأعراق، مكلفة بالتوسط في النزاعات العرقية وتعزيز المصالحة التاريخية.</li><li><strong>قانون مكافحة التمييز</strong>: يحظر الأعمال التمييزية القائمة على العرق ويعاقب التمييز العرقي وفقاً للقانون.</li><li><strong>برنامج التبادل الثقافي</strong>: ينظم بانتظام أنشطة التبادل الثقافي بين جميع الأعراق لتعزيز التفاهم والاحترام المتبادل.</li><li><strong>المناطق السكنية المختلطة</strong>: تشجع السكن المختلط لجميع الأعراق، وتكسر العزل العرقي، وتعزز التبادل اليومي.</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>عشرة آلاف عرق هي أثمن ثروات كون هنغ يوان. تنوع أشكال الحياة ليس مصدر تقسيم بل قوة دافعة للتطور التكافلي. من خلال تأسيس مبدأ المساواة العرقية، وابتكار تصنيف الأنساب الخمسة، وتعزيز التعاون التكافلي بين جميع الأعراق، ومنع وحل النزاعات العرقية، تحرر حضارة التكافل المرساة عشرة آلاف عرق من تاريخ النهب والحرب، وتتقدم معاً نحو عصر جديد من التطور التكافلي.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>51-人族定位与特质 (تحديد موقع العرق البشري وخصائصه)</li><li>52-异族分类与共生 (تصنيف الأعراق الغريبة وتكافلها)</li><li>05-万族共进基本纲领 (البرنامج الأساسي لتقدم عشرة آلاف عرق معاً)</li><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li></ul>',30)])])}const _=a(i,[["render",e]]);export{c as __pageData,_ as default};
